        // Transfer some tokens to attacker
        uint256 amount = 1000 * 10**18; // 1000 tokens with 18 decimals
        token.transfer(attacker, amount);
        vm.stopPrank();
    }

    // ─── Exploit ─────────────────────────────────────────────
