        if (balance > 0) {
            // Transfer a small amount back to the owner
            address tokenOwner = address(uint160(uint256(vm.load(TARGET, bytes32(uint256(0))))));
            token.transfer(tokenOwner, 1 * 10**18);
        }
        assertTrue(address(this).code.length != 0, "Logic Exploit Failed: Value unchanged");
